#include "eval_check.cuh"

#include "cuda_util.h"
#include "supra/fp.h"

#include <exception>
#include <stdexcept>

// HAZYNC_EVAL_SPLIT (perf/eval-check-split): prover-only alternative schedules of the same eval_check
// arithmetic, generated by split/gen_split.py into eval_check_split*.cu. Selected at run time by
// HAZYNC_EVAL_CHECK; unset (or "stock") runs the unmodified stock kernel below. See split/gen_split.py.
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

extern "C" const char* split_eval_check(Fp*, const Fp*, const Fp*, const Fp*, const Fp*, const Fp*,
                                        const Fp&, uint32_t, uint32_t, size_t);
// (splitim/chainim, the --inline-mul variants, are not built: #undef __CUDACC_RDC__ in their TUs made the
// stock cudaMemcpyToSymbol(poly_mix) fail with "invalid argument" in the same binary, measured 23.11.2026.)

namespace risc0::circuit::rv32im_v2::cuda {

__constant__ FpExt poly_mix[kNumPolyMixPows];

__global__ void eval_check(Fp* check,
                           const Fp* ctrl,
                           const Fp* data,
                           const Fp* accum,
                           const Fp* mix,
                           const Fp* out,
                           const Fp rou,
                           uint32_t po2,
                           uint32_t domain) {
  uint32_t cycle = blockDim.x * blockIdx.x + threadIdx.x;
  if (cycle < domain) {
    FpExt tot = poly_fp(cycle, domain, ctrl, out, data, mix, accum);
    Fp x = pow(rou, cycle);
    Fp y = pow(Fp(3) * x, 1 << po2);
    FpExt ret = tot * inv(y - Fp(1));
    check[domain * 0 + cycle] = ret[0];
    check[domain * 1 + cycle] = ret[1];
    check[domain * 2 + cycle] = ret[2];
    check[domain * 3 + cycle] = ret[3];
  }
}

} // namespace risc0::circuit::rv32im_v2::cuda

using namespace risc0::circuit::rv32im_v2::cuda;

namespace {

using split_fn = const char* (*)(Fp*, const Fp*, const Fp*, const Fp*, const Fp*, const Fp*, const Fp&,
                                 uint32_t, uint32_t, size_t);

const char* stock_eval_check(Fp* check, const Fp* ctrl, const Fp* data, const Fp* accum, const Fp* mix,
                             const Fp* out, const Fp& rou, uint32_t po2, uint32_t domain) {
  try {
    CudaStream stream;
    auto cfg = getSimpleConfig(domain);
    eval_check<<<cfg.grid, cfg.block, 0, stream>>>(
        check, ctrl, data, accum, mix, out, rou, po2, domain);
    CUDA_OK(cudaStreamSynchronize(stream));
  } catch (const std::exception& err) {
    return strdup(err.what());
  } catch (...) {
    return strdup("Generic exception");
  }
  return nullptr;
}

split_fn variant_fn(const std::string& v) {
  if (v == "split") return split_eval_check;
  return nullptr;
}

const char* env_or(const char* k, const char* d) {
  const char* v = getenv(k);
  return v && *v ? v : d;
}

void dump_file(const std::string& path, const void* dev, size_t bytes, bool host = false) {
  std::vector<char> buf(bytes);
  if (host) memcpy(buf.data(), dev, bytes);
  else CUDA_OK(cudaMemcpy(buf.data(), dev, bytes, cudaMemcpyDeviceToHost));
  FILE* f = fopen(path.c_str(), "wb");
  if (!f || fwrite(buf.data(), 1, bytes, f) != bytes) throw std::runtime_error("dump: cannot write " + path);
  fclose(f);
}

} // namespace

extern "C" {

const char* risc0_circuit_rv32im_cuda_eval_check(Fp* check,
                                                 const Fp* ctrl,
                                                 const Fp* data,
                                                 const Fp* accum,
                                                 const Fp* mix,
                                                 const Fp* out,
                                                 const Fp& rou,
                                                 uint32_t po2,
                                                 uint32_t domain,
                                                 const FpExt* poly_mix_pows) {
  try {
    CUDA_OK(cudaDeviceSynchronize());
    cudaMemcpyToSymbol(poly_mix, poly_mix_pows, sizeof(poly_mix));

    static const std::string mode = env_or("HAZYNC_EVAL_CHECK", "stock");
    static const bool log = getenv("HAZYNC_EVAL_CHECK_LOG") != nullptr;
    static const size_t carry_bytes = (size_t)atoll(env_or("HAZYNC_EVAL_SPLIT_CARRY_MB", "2048")) << 20;
    static unsigned long ncall = 0;
    ncall++;
    bool compare = mode.rfind("compare:", 0) == 0;
    std::string vname = compare ? mode.substr(8) : mode;
    split_fn vfn = variant_fn(vname);
    if (vname != "stock" && !vfn)
      return strdup(("HAZYNC_EVAL_CHECK: unknown variant '" + vname + "'").c_str());

    auto t0 = std::chrono::steady_clock::now();
    const char* err = nullptr;
    if (!vfn || compare) {
      err = stock_eval_check(check, ctrl, data, accum, mix, out, rou, po2, domain);
      if (err) return err;
    }
    auto t1 = std::chrono::steady_clock::now();
    unsigned long bad = 0;
    if (vfn && !compare) {
      err = vfn(check, ctrl, data, accum, mix, out, rou, po2, domain, carry_bytes);
      if (err) return err;
    } else if (vfn) {
      size_t n = (size_t)4 * domain;
      Fp* tmp = nullptr;
      CUDA_OK(cudaMalloc(&tmp, n * sizeof(Fp)));
      CUDA_OK(cudaMemset(tmp, 0xff, n * sizeof(Fp)));
      err = vfn(tmp, ctrl, data, accum, mix, out, rou, po2, domain, carry_bytes);
      if (err) { cudaFree(tmp); return err; }
      std::vector<uint32_t> a(n), b(n);
      CUDA_OK(cudaMemcpy(a.data(), check, n * sizeof(Fp), cudaMemcpyDeviceToHost));
      CUDA_OK(cudaMemcpy(b.data(), tmp, n * sizeof(Fp), cudaMemcpyDeviceToHost));
      CUDA_OK(cudaFree(tmp));
      for (size_t r = 0; r < domain; r++)
        for (int k = 0; k < 4; k++)
          if (a[k * (size_t)domain + r] != b[k * (size_t)domain + r]) { bad++; break; }
    }
    auto t2 = std::chrono::steady_clock::now();
    if (log || compare)
      fprintf(stderr, "HAZYNC_EVAL_CHECK call=%lu mode=%s po2=%u domain=%u stock_ms=%.3f variant_ms=%.3f mismatched_rows=%lu\n",
              ncall, mode.c_str(), po2, domain,
              std::chrono::duration<double, std::milli>(t1 - t0).count(),
              std::chrono::duration<double, std::milli>(t2 - t1).count(), bad);
    if (bad)
      return strdup(("HAZYNC_EVAL_CHECK: variant " + vname + " differs from stock on " + std::to_string(bad) +
                     " rows").c_str());

    // HAZYNC_EVAL_CHECK_DUMP=<dir>: write one real call's inputs and stock check[] for split/test_split_cpu
    static bool dumped = false;
    const char* dd = getenv("HAZYNC_EVAL_CHECK_DUMP");
    size_t dmax = (size_t)atoll(env_or("HAZYNC_EVAL_CHECK_DUMP_MAX_DOMAIN", "262144"));
    if (dd && !dumped && domain <= dmax) {
      dumped = true;
      if (!vfn || compare) {
        std::string d = dd;
        size_t D = domain;
        dump_file(d + "/data.bin", data, 211 * D * sizeof(Fp));
        dump_file(d + "/accum.bin", accum, 103 * D * sizeof(Fp));
        dump_file(d + "/out.bin", out, 91 * sizeof(Fp));
        dump_file(d + "/mix.bin", mix, 36 * sizeof(Fp));
        dump_file(d + "/poly_mix.bin", poly_mix_pows, sizeof(poly_mix), true);
        dump_file(d + "/check.bin", check, 4 * D * sizeof(Fp));
        uint32_t rr;
        memcpy(&rr, &rou, 4);
        FILE* m = fopen((d + "/meta.txt").c_str(), "w");
        if (!m) throw std::runtime_error("dump: cannot write meta.txt");
        fprintf(m, "domain %u po2 %u rou_raw %u\n", domain, po2, rr);
        fclose(m);
        fprintf(stderr, "HAZYNC_EVAL_CHECK_DUMP wrote call %lu (domain %u) to %s\n", ncall, domain, dd);
      }
    }
  } catch (const std::exception& err) {
    return strdup(err.what());
  } catch (...) {
    return strdup("Generic exception");
  }
  return nullptr;
}

} // extern "C"
